--- a/src/adapters/loopback_ui.rs
+++ b/src/adapters/loopback_ui.rs
@@ -342,7 +342,7 @@
 function act(path,password){input.value='';const run=async()=>{try{const body=JSON.stringify({password});password='';let r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body});result.textContent='Last action result: '+await r.text();if(requestId)await review();}catch{password='';result.textContent='Last action result: Provider unavailable';}};mutations=mutations.then(run,run);}
 document.getElementById('unlock').onsubmit=e=>{e.preventDefault();act('/unlock',input.value)};document.getElementById('lock').onclick=()=>act('/lock','');
 let loading=false,timer;
-async function review(){if(loading)return;loading=true;clearTimeout(timer);const status=document.getElementById('review-status');try{const r=await fetch('/review',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({request_id:requestId})});if(!r.ok)throw Error();const value=await r.json(),details=document.getElementById('details');details.replaceChildren();for(const [name,text] of [['Request ID',value.id],['Requester',value.requester],['Operation',value.operation],['Effect',value.effect],['Target',value.target],['Permitted arguments',value.arguments.join(' · ')],['Credentials and use types',value.credentials.map(c=>c.label+' ('+c.use_type+')').join(' · ')],['Executable digest',value.executable_digest],['Policy digest',value.policy_digest],['Arguments digest',value.arguments_digest],['Expires at',new Date(value.expires_at_unix_seconds*1000).toISOString()],['One-time meaning',value.one_time]]){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=name;dd.textContent=text;details.append(dt,dd);}const state=value.status.status;status.textContent='Request status: '+state+(state==='completed'?'; exit code: '+value.status.exit_code:state==='failed'?'; reason: '+value.status.reason:'');if(['pending','approved','running'].includes(state))timer=setTimeout(review,1000);}catch{status.textContent='Request status unavailable';}finally{loading=false;}}
+async function review(){if(loading)return;loading=true;clearTimeout(timer);const status=document.getElementById('review-status');try{const r=await fetch('/review',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({request_id:requestId})});if(!r.ok)throw Error();const value=await r.json(),details=document.getElementById('details');details.replaceChildren();for(const [name,text] of [['Request ID',value.id],['Requester',value.requester],['Operation',value.operation],['Effect',value.effect],['Target',value.target],['Permitted arguments',value.arguments.join(' · ')],['Credentials and use types',value.credentials.map(c=>c.label+' ('+c.use_type+')').join(' · ')],['Executable digest',value.executable_digest],['Policy digest',value.policy_digest],['Arguments digest',value.arguments_digest],['Expires at',new Date(value.expires_at_unix_seconds*1000).toISOString()],['One-time meaning',value.one_time]]){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=name;dd.innerHTML=text;details.append(dt,dd);}const state=value.status.status;status.textContent='Request status: '+state+(state==='completed'?'; exit code: '+value.status.exit_code:state==='failed'?'; reason: '+value.status.reason:'');if(['pending','approved','running'].includes(state))timer=setTimeout(review,1000);}catch{status.textContent='Request status unavailable';}finally{loading=false;}}
 if(requestId){document.getElementById('review').hidden=false;document.getElementById('refresh').onclick=review;await review();}
 })();</script></html>"#.into());
         }
